 1→/**
 2→ * narrative-types.ts — Prism 叙事报告结构（路B / DR-39）
 3→ *
 4→ * 分析师探索出 findings 后，"叙事阶段"让 LLM 读自己的 findings，写出这份 NarrativeReport——
 5→ * 只含给人阅读的内容（概览/问题先行/主题分群/线程/优先级），**审计信息(证据链/自审/技术论证)
 6→ * 完全不进这里**，它们留在 findings.json 供核查。renderer 只渲染 NarrativeReport + 调用树可视化。
 7→ *
 8→ * 对标 narrative_sample.md 的叙事结构，让报告"不弱于、强于作文机"。
 9→ */
10→
11→/** 一棵调用树节点（渲染时由 renderer 重查 drillDownMarker 填充真实数据；叙事阶段只需给出 rootMarker） */
12→export interface CallTreeRef {
13→  /** 要展示调用树的根 marker（renderer 会重查它拿结构化树 + 上色渲染） */
14→  rootMarker: string;
15→  /** 可选：叙事作者对这棵树想强调的一句话（如"82%是自身逻辑，子节点只占18%"） */
16→  note?: string;
17→}
18→
19→/** 一个"问题项"——可以是一条发现，也可以是几条发现合起来讲的一个主题 */
20→export interface NarrativeItem {
21→  /** 关联的 finding id（一个或多个——多个=把几条发现合并成一个主题叙事） */
22→  findingIds: string[];
23→  /** 小节标题（人话，如"行军线管理：每帧2.3ms的常驻税"） */
24→  title: string;
25→  /** 叙事正文（人话，讲清什么问题/多严重/为什么/对玩家啥影响。可跨 finding 串联） */
26→  narrative: string;
27→  /** 可选：调用树可视化（renderer 重查渲染） */
28→  callTree?: CallTreeRef;
29→  /** 可选：源码归因（读到真实代码时，讲代码里的具体问题——如"三个每帧全量foreach"） */
30→  sourceInsight?: string;
31→  /** 优化建议（编号列表，每条可落地） */
32→  recommendations: string[];
33→  /** 严重度（叙事作者按"对整体帧率的贡献"判定，不按单帧峰值） */
34→  severity: 'critical' | 'high' | 'medium' | 'low' | 'info';
35→}
36→
37→/** 一个主题群（如"稳态开销群"/"偶发尖峰群"/"工作线程"/"已排除"） */
38→export interface NarrativeSection {
39→  /** 群标题（如"稳态开销：决定帧率天花板的常驻税"） */
40→  heading: string;
41→  /** 群导语（一段话，讲这一组问题的共性——如"这三项每帧都在，合计6.6ms/帧"） */
42→  intro?: string;
43→  items: NarrativeItem[];
44→}
45→
46→/** 三维定性维度：热点主要属于哪一类（可多选） */
47→export type HotspotDimension = 'absoluteCost' | 'shareHigh' | 'outlier';
48→
49→/** 单源可判性：这条结论单源能不能下定论 */
50→export type HotspotJudgability = 'judgable' | 'needsBaseline' | 'needsDomainKnowledge';
51→
52→/** 核心结论表的一行（问题先行，按整体贡献排序） */
53→export interface TopConclusionRow {
54→  rank: number;
55→  problem: string;       // 问题名
56→  kind: string;          // 类型：稳态大头 / 高频尖峰 / 低频尖峰
57→  contribution: string;  // 对整体的贡献（如"每帧2.3ms×600=1381ms，全场self最高"）
58→  severity: 'critical' | 'high' | 'medium' | 'low' | 'info';
59→  /** 三维定性：这个热点主要属于哪一类（可多选）。absoluteCost=绝对量大/占帧预算显著；shareHigh=占总量/贡献度高；outlier=离群严重(spikeRatio/p99高) */
60→  dimensions?: HotspotDimension[];
61→  /** 单源可判性：这条结论单源能不能下定论。judgable=能判(有绝对基线/内生可比)；needsBaseline=该不该管需历史基线；needsDomainKnowledge=需业务知识 */
62→  judgability?: HotspotJudgability;
63→}
64→
65→export interface NarrativeReport {
66→  runId: string;
67→  /** 一、概览：一句话讲清整体故事（如"稳态打底+尖峰捅刀"） */
68→  overview: string;
69→  /** 判定（沿用 verdict） */
70→  rating: 'excellent' | 'pass' | 'weak' | 'fail';
71→  /** 二、核心结论表（问题先行，按整体贡献排序） */
72→  topConclusions: TopConclusionRow[];
73→  /** 判定边界诚实声明：单源这次能确定什么、判不了什么（超越作文机的"知道自己边界"）。可选。 */
74→  judgmentBoundary?: { canJudge: string[]; cannotJudge: string[] };
75→  /** 已排除项（查证后确认不是问题的——作文机没有的"辨伪"能力） */
76→  ruledOut?: { name: string; why: string }[];
77→  /** 三~五、主题分群（稳态/尖峰/线程等，由叙事作者自己组织，不写死） */
78→  sections: NarrativeSection[];
79→  /** 六、优化优先级汇总（P0/P1/P2 + 补采需求） */
80→  prioritySummary: { priority: string; action: string; benefit: string }[];
81→}
82→

  1→/**
  2→ * render-html.ts — Prism HTML report renderer (deterministic, no LLM).
  3→ *
  4→ * Usage (from cwd web/):
  5→ *   node --import tsx server/prism/render-html.ts --dir <run-output-dir>
  6→ *
  7→ * Reads:   <dir>/narrative.json  (required — NarrativeReport shape)
  8→ *          <dir>/verdict.json    (optional — numeric metric strip)
  9→ * Outputs: <dir>/report.html
 10→ *
 11→ * Features:
 12→ * - Self-contained HTML (inline CSS + JS, opens by double-click)
 13→ * - Dark Unity-Timeline-inspired theme
 14→ * - Narrative-flow structure: overview → topConclusions → sections → prioritySummary
 15→ * - Flame-bar call-tree re-queried from real DB at render time (drillDownMarker)
 16→ * - Zero audit info (证据链/自我审查/技术论证) — narrative.json has none
 17→ */
 18→
 19→import * as fs from 'fs';
 20→import * as path from 'path';
 21→import { openPrismDb } from './db.js';
 22→import { drillDownMarker } from './tools.js';
 23→import type { DrillDownNode } from './tools.js';
 24→import type { NarrativeReport, NarrativeItem } from './narrative-types.js';
 25→
 26→// ─────────────────────── Verdict numeric metrics shape ───────────────────────
 27→
 28→interface Verdict {
 29→  runId?: string;
 30→  rating?: string;
 31→  frameBudgetMs?: number;
 32→  observedP50Ms?: number;
 33→  observedP95Ms?: number;
 34→  observedP99Ms?: number;
 35→  observedMaxMs?: number;
 36→  observedMaxFrameIndex?: number;
 37→  pctFramesOverBudget?: number;
 38→}
 39→
 40→// ─────────────────────── Tiny helpers ───────────────────────
 41→
 42→function htmlEsc(s: unknown): string {
 43→  if (s == null) return '';
 44→  return String(s)
 45→    .replace(/&/g, '&amp;')
 46→    .replace(/</g, '&lt;')
 47→    .replace(/>/g, '&gt;')
 48→    .replace(/"/g, '&quot;')
 49→    .replace(/'/g, '&#39;');
 50→}
 51→
 52→function num(v: unknown, digits = 1): string {
 53→  if (typeof v === 'number' && isFinite(v)) return v.toFixed(digits);
 54→  return '—';
 55→}
 56→
 57→/** Category color from marker name (Unity Timeline palette). */
 58→function categoryColor(markerName: string): { bg: string; border: string; text: string } {
 59→  const n = markerName.toLowerCase();
 60→  if (/gc\.|collect|alloc|garbage/.test(n))
 61→    return { bg: '#f443361a', border: '#f44336', text: '#ff7961' };
 62→  if (/wait|semaphore|idle|sync|present/.test(n))
 63→    return { bg: '#9e9e9e1a', border: '#757575', text: '#bdbdbd' };
 64→  if (/render|urp|gfx|draw|mesh|vr|blit|shadow|depth|pass|camera/.test(n))
 65→    return { bg: '#4caf501a', border: '#4caf50', text: '#81c784' };
 66→  if (/update|mgr|manager|cs:|lua|script|behaviour|mono/.test(n))
 67→    return { bg: '#2196f31a', border: '#2196f3', text: '#64b5f6' };
 68→  if (/job|worker|burst|thread|batch/.test(n))
 69→    return { bg: '#9c27b01a', border: '#9c27b0', text: '#ce93d8' };
 70→  if (/network|server|ntf|msg|socket|tserver/.test(n))
 71→    return { bg: '#0096881a', border: '#009688', text: '#4db6ac' };
 72→  return { bg: '#78909c1a', border: '#546e7a', text: '#90a4ae' };
 73→}
 74→
 75→const SEV_CN: Record<string, string> = {
 76→  critical: '严重', high: '高', medium: '中', low: '低', info: '信息',
 77→};
 78→const SEV_COLOR: Record<string, { dot: string; badge: string }> = {
 79→  critical: { dot: '#f44336', badge: '#f4433620' },
 80→  high:     { dot: '#ff9800', badge: '#ff980020' },
 81→  medium:   { dot: '#ffc107', badge: '#ffc10720' },
 82→  low:      { dot: '#4caf50', badge: '#4caf5020' },
 83→  info:     { dot: '#2196f3', badge: '#2196f320' },
 84→};
 85→const KIND_CN: Record<string, string> = {
 86→  '稳态大头': '稳态大头', '高频尖峰': '高频尖峰', '低频尖峰': '低频尖峰',
 87→};
 88→const RATING_MAP: Record<string, { emoji: string; label: string; color: string; bg: string }> = {
 89→  excellent: { emoji: '🟢', label: '优秀',  color: '#4caf50', bg: '#4caf5020' },
 90→  pass:      { emoji: '🟢', label: '及格',  color: '#8bc34a', bg: '#8bc34a20' },
 91→  weak:      { emoji: '🟡', label: '偏弱',  color: '#ffc107', bg: '#ffc10720' },
 92→  fail:      { emoji: '🔴', label: '不合格', color: '#f44336', bg: '#f4433620' },
 93→};
 94→
 95→function sevStyle(sev: string): { dot: string; badge: string } {
 96→  return SEV_COLOR[sev] ?? { dot: '#9e9e9e', badge: '#9e9e9e20' };
 97→}
 98→
 99→/** Theme-group accent colors — cycle by section index, not by heading name. */
100→const SECTION_GROUP_COLORS = [
101→  { border: '#2196f3', bg: '#2196f318' },
102→  { border: '#ff9800', bg: '#ff980018' },
103→  { border: '#9c27b0', bg: '#9c27b018' },
104→  { border: '#78909c', bg: '#78909c18' },
105→  { border: '#4caf50', bg: '#4caf5018' },
106→  { border: '#009688', bg: '#00968818' },
107→];
108→
109→function sectionGroupColor(index: number): { border: string; bg: string } {
110→  return SECTION_GROUP_COLORS[index % SECTION_GROUP_COLORS.length];
111→}
112→
113→// ─────────────────────── Call-tree rendering ───────────────────────
114→
115→function renderTreeHTML(node: DrillDownNode, rootMs: number, depth: number): string {
116→  const totalMs = node.totalMsPerFrame;
117→  const widthPct = rootMs > 0 ? Math.max(1, (totalMs / rootMs) * 100) : 100;
118→  const col = categoryColor(node.name);
119→  const indent = depth * 20;
120→
121→  const displayMs =
122→    node.selfMsPerFrame > 0 && node.selfMsPerFrame < totalMs
123→      ? `${totalMs.toFixed(2)}ms (self ${node.selfMsPerFrame.toFixed(2)}ms)`
124→      : `${totalMs.toFixed(2)}ms`;
125→  const pctStr = (node.pctOfRoot * 100).toFixed(1);
126→
127→  let html = `
128→  <div class="tree-row" style="--tree-indent:${indent}px;--tree-width:${widthPct.toFixed(1)}%;--tree-bg:${col.bg};--tree-border:${col.border};">
129→    <div class="tree-bar">
130→      <span class="tree-fill" aria-hidden="true"></span>
131→      <span class="tree-label" style="color:${col.text}" title="${htmlEsc(node.name)}">${htmlEsc(node.name)}</span>
132→      <span class="tree-ms">${htmlEsc(displayMs)}</span>
133→      <span class="tree-pct">${pctStr}%</span>
134→    </div>
135→  </div>`;
136→
137→  for (const child of node.children ?? []) {
138→    html += renderTreeHTML(child, rootMs, depth + 1);
139→  }
140→  return html;
141→}
142→
143→const TREE_LEGEND = `
144→  <span class="legend-item" style="color:#81c784">■ 渲染</span>
145→  <span class="legend-item" style="color:#64b5f6">■ 脚本</span>
146→  <span class="legend-item" style="color:#ff7961">■ GC/内存</span>
147→  <span class="legend-item" style="color:#bdbdbd">■ 等待</span>
148→  <span class="legend-item" style="color:#ce93d8">■ Job</span>
149→  <span class="legend-item" style="color:#4db6ac">■ 网络</span>`;
150→
151→// ─────────────────────── Narrative item card ───────────────────────
152→
153→function renderItemCard(item: NarrativeItem, tree: DrillDownNode | null | undefined): string {
154→  const sc = sevStyle(item.severity);
155→
156→  // Flame-bar tree (or fallback note)
157→  let treeSection = '';
158→  if (tree) {
159→    const rootMs = tree.totalMsPerFrame;
160→    treeSection = `
161→    <div class="tree-section">
162→      <div class="tree-header">
163→        <span class="tree-title">调用树（per-frame avg）</span>
164→        <span class="tree-legend">${TREE_LEGEND}</span>
165→      </div>
166→      <div class="tree-container">
167→        ${renderTreeHTML(tree, rootMs, 0)}
168→      </div>
169→    </div>`;
170→  } else if (item.callTree?.note) {
171→    treeSection = `
172→    <div class="tree-section fallback">
173→      <div class="tree-header"><span class="tree-title">调用树备注</span></div>
174→      <div class="tree-note">${htmlEsc(item.callTree.note)}</div>
175→    </div>`;
176→  }
177→
178→  // sourceInsight callout
179→  const insightSection = item.sourceInsight
180→    ? `<div class="source-insight"><span class="insight-label">源码归因</span>${htmlEsc(item.sourceInsight).replace(/\n/g, '<br>')}</div>`
181→    : '';
182→
183→  // Recommendations numbered list
184→  const recsHTML = item.recommendations.length
185→    ? `<div class="rec-section">
186→        <div class="rec-label">优化建议</div>
187→        <ol class="rec-list">${item.recommendations.map(r => `<li>${htmlEsc(r)}</li>`).join('')}</ol>
188→      </div>`
189→    : '';
190→
191→  return `
192→  <div class="item-card">
193→    <div class="item-header">
194→      <span class="sev-dot" style="background:${sc.dot}" title="${SEV_CN[item.severity] ?? item.severity}"></span>
195→      <span class="item-title">${htmlEsc(item.title)}</span>
196→      <span class="chip sev-chip" style="color:${sc.dot};background:${sc.badge}">${SEV_CN[item.severity] ?? item.severity}</span>
197→    </div>
198→    <div class="item-body">
199→      <p class="narrative-text">${htmlEsc(item.narrative).replace(/\n/g, '<br>')}</p>
200→      ${treeSection}
201→      ${insightSection}
202→      ${recsHTML}
203→    </div>
204→  </div>`;
205→}
206→
207→// ─────────────────────── Main HTML builder ───────────────────────
208→
209→interface RenderOptions {
210→  narrative: NarrativeReport;
211→  verdict: Verdict | null;
212→  treesByItemKey: Map<string, DrillDownNode | null>;
213→}
214→
215→function renderHTML(opts: RenderOptions): string {
216→  const { narrative, verdict, treesByItemKey } = opts;
217→
218→  const ratingInfo = RATING_MAP[narrative.rating] ?? { emoji: '—', label: narrative.rating ?? '—', color: '#9e9e9e', bg: '#9e9e9e20' };
219→
220→  // ── Metrics strip ──
221→  const budget = verdict?.frameBudgetMs ?? null;
222→  const fps = budget ? Math.round(1000 / budget) : null;
223→  const metrics = [
224→    { label: '帧预算',  value: budget ? `${num(budget)}ms / ${fps}fps` : '—' },
225→    { label: 'P50',    value: verdict?.observedP50Ms != null ? `${num(verdict.observedP50Ms)}ms` : '—' },
226→    { label: 'P95',    value: verdict?.observedP95Ms != null ? `${num(verdict.observedP95Ms)}ms` : '—' },
227→    { label: 'P99',    value: verdict?.observedP99Ms != null ? `${num(verdict.observedP99Ms)}ms` : '—' },
228→    { label: '最差帧', value: verdict?.observedMaxMs != null
229→        ? (verdict.observedMaxFrameIndex != null
230→          ? `${num(verdict.observedMaxMs)}ms (#${verdict.observedMaxFrameIndex})`
231→          : `${num(verdict.observedMaxMs)}ms`)
232→        : '—' },
233→    { label: '超预算%', value: verdict?.pctFramesOverBudget != null ? `${num(verdict.pctFramesOverBudget)}%` : '—' },
234→  ];
235→  const metricsHTML = metrics.map(m => `
236→  <div class="metric-box">
237→    <div class="metric-label">${htmlEsc(m.label)}</div>
238→    <div class="metric-value">${htmlEsc(m.value)}</div>
239→  </div>`).join('');
240→
241→  // ── § 核心结论 table ──
242→  const conclusionsHTML = narrative.topConclusions.map(row => {
243→    const sc = sevStyle(row.severity);
244→    return `<tr>
245→      <td class="tc-rank">${row.rank}</td>
246→      <td class="tc-problem">${htmlEsc(row.problem)}</td>
247→      <td class="tc-kind">${htmlEsc(KIND_CN[row.kind] ?? row.kind)}</td>
248→      <td class="tc-contribution">${htmlEsc(row.contribution)}</td>
249→      <td class="tc-severity"><span class="chip sev-chip" style="color:${sc.dot};background:${sc.badge}">${SEV_CN[row.severity] ?? row.severity}</span></td>
250→    </tr>`;
251→  }).join('');
252→
253→  // ── ruledOut strip ──
254→  const ruledOutHTML = (narrative.ruledOut ?? []).length
255→    ? `<div class="ruled-out-strip">
256→        <span class="ruled-out-label">已排除</span>
257→        ${narrative.ruledOut!.map(r => `<span class="ruled-out-item" title="${htmlEsc(r.why)}">${htmlEsc(r.name)}: <em>${htmlEsc(r.why)}</em></span>`).join('')}
258→      </div>`
259→    : '';
260→
261→  // ── TOC anchors ──
262→  const tocItems = [
263→    { label: '核心结论', id: 'sec-core-conclusions' },
264→    ...narrative.sections.map((sec, i) => ({ label: sec.heading, id: `sec-section-${i}` })),
265→    { label: '优化优先级', id: 'sec-priority' },
266→  ];
267→  const tocHTML = `
268→<div class="toc-block">
269→  <div class="toc-title">目录</div>
270→  <ul class="toc-list">
271→    ${tocItems.map(item => `<li><a href="#${item.id}">${htmlEsc(item.label)}</a></li>`).join('')}
272→  </ul>
273→</div>`;
274→
275→  // ── § sections ──
276→  const sectionsHTML = narrative.sections.map((sec, secIdx) => {
277→    const gc = sectionGroupColor(secIdx);
278→    const introHTML = sec.intro
279→      ? `<p class="section-intro">${htmlEsc(sec.intro).replace(/\n/g, '<br>')}</p>`
280→      : '';
281→    const itemsHTML = sec.items.map((item, i) => {
282→      const key = `${sec.heading}::${i}`;
283→      const tree = treesByItemKey.get(key);
284→      return renderItemCard(item, tree);
285→    }).join('');
286→    return `
287→  <div class="narrative-section">
288→    <div class="section-heading" id="sec-section-${secIdx}" style="border-left:4px solid ${gc.border};background:${gc.bg}">
289→      ${htmlEsc(sec.heading)}
290→    </div>
291→    ${introHTML}
292→    <div class="items-list">${itemsHTML}</div>
293→  </div>`;
294→  }).join('');
295→
296→  // ── § 优化优先级 ──
297→  const priorityHTML = narrative.prioritySummary.map(row => {
298→    const isP0 = row.priority === 'P0';
299→    return `<tr class="${isP0 ? 'priority-p0' : ''}">
300→      <td class="pri-priority">${htmlEsc(row.priority)}</td>
301→      <td class="pri-action">${htmlEsc(row.action)}</td>
302→      <td class="pri-benefit">${htmlEsc(row.benefit)}</td>
303→    </tr>`;
304→  }).join('');
305→
306→  return `<!DOCTYPE html>
307→<html lang="zh-CN">
308→<head>
309→<meta charset="UTF-8">
310→<meta name="viewport" content="width=device-width,initial-scale=1">
311→<title>Prism 性能报告 · ${htmlEsc(narrative.runId)}</title>
312→<style>
313→:root {
314→  --bg: #0f0f1a;
315→  --surface: #1a1a2e;
316→  --surface2: #16213e;
317→  --surface3: #0f3460;
318→  --border: #2a2a4a;
319→  --text: #e0e0e0;
320→  --text-muted: #888;
321→  --accent: #7c4dff;
322→  --accent2: #00e5ff;
323→  --font-mono: 'Consolas', 'Courier New', monospace;
324→  --font-ui: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
325→  --radius: 8px;
326→  --radius-sm: 4px;
327→}
328→* { box-sizing: border-box; margin: 0; padding: 0; }
329→html { scroll-behavior: smooth; }
330→body {
331→  background: var(--bg);
332→  color: var(--text);
333→  font-family: var(--font-ui);
334→  font-size: 14px;
335→  line-height: 1.6;
336→  padding: 28px 32px;
337→  min-height: 100vh;
338→  max-width: 1200px;
339→  margin: 0 auto;
340→}
341→a { color: var(--accent2); }
