849→// ─────────────────────── Re-query call trees ───────────────────────
850→
851→async function requeryTrees(
852→  narrative: NarrativeReport,
853→  dbPath: string | undefined,
854→): Promise<Map<string, DrillDownNode | null>> {
855→  const map = new Map<string, DrillDownNode | null>();
856→
857→  // Collect items with callTree.rootMarker
858→  type ItemRef = { key: string; rootMarker: string };
859→  const refs: ItemRef[] = [];
860→  for (const sec of narrative.sections) {
861→    sec.items.forEach((item, i) => {
862→      if (item.callTree?.rootMarker) {
863→        refs.push({ key: `${sec.heading}::${i}`, rootMarker: item.callTree.rootMarker });
864→      }
865→    });
866→  }
867→
868→  if (refs.length === 0) return map;
869→
870→  let db: ReturnType<typeof openPrismDb> | null = null;
871→  try {
872→    db = openPrismDb(dbPath);
873→  } catch (e) {
874→    console.error('[render-html] Cannot open DB — all callTrees will show note text:', (e as Error).message);
875→    return map;
876→  }
877→
878→  for (const ref of refs) {
879→    try {
880→      const result = drillDownMarker(db, {
881→        runId: narrative.runId,
882→        rootMarker: ref.rootMarker,
883→        maxDepth: 6,
884→        minMsPerFrame: 0.05,
885→        topPerLevel: 8,
886→      });
887→      const tree = result.data.tree;
888→      map.set(ref.key, tree);
889→      console.log(`[render-html] tree OK: "${ref.rootMarker}" → ${result.data.rootTotalMsPerFrame.toFixed(2)}ms/frame`);
890→    } catch (e) {
891→      console.warn(`[render-html] tree FAIL: "${ref.rootMarker}" — ${(e as Error).message}`);
892→      map.set(ref.key, null);
893→    }
894→  }
895→
896→  try { db.close(); } catch { /* ignore */ }
897→  return map;
898→}
