900→// ─────────────────────── CLI entry ───────────────────────
901→
902→function getFlag(name: string): string | undefined {
903→  const i = process.argv.indexOf(name);
904→  return i >= 0 && process.argv[i + 1] ? process.argv[i + 1] : undefined;
905→}
906→
907→async function main(): Promise<void> {
908→  const dir = getFlag('--dir') ?? 'data/prism-out/unity-outside-stressmove';
909→
910→  // Require narrative.json — do NOT fall back to findings.json
911→  const narrativePath = path.join(dir, 'narrative.json');
912→  if (!fs.existsSync(narrativePath)) {
913→    console.error(`[render-html] ERROR: narrative.json not found at ${narrativePath}`);
914→    console.error('[render-html] This renderer requires narrative.json (NarrativeReport shape). Run the narrative stage first.');
915→    process.exit(1);
916→  }
917→
918→  let narrative: NarrativeReport;
919→  try {
920→    narrative = JSON.parse(fs.readFileSync(narrativePath, 'utf-8')) as NarrativeReport;
921→  } catch (e) {
922→    console.error(`[render-html] ERROR: failed to parse narrative.json — ${(e as Error).message}`);
923→    process.exit(1);
924→  }
925→
926→  // Optional verdict.json for numeric metrics
927→  let verdict: Verdict | null = null;
928→  const verdictPath = path.join(dir, 'verdict.json');
929→  if (fs.existsSync(verdictPath)) {
930→    try {
931→      verdict = JSON.parse(fs.readFileSync(verdictPath, 'utf-8')) as Verdict;
932→    } catch {
933→      console.warn('[render-html] verdict.json found but failed to parse — metric strip will show "—"');
934→    }
935→  }
936→
937→  const dbPath = getFlag('--db');
938→  console.log(`[render-html] dir=${dir}  runId=${narrative.runId}  rating=${narrative.rating}`);
939→  console.log(`[render-html] sections=${narrative.sections.length}  topConclusions=${narrative.topConclusions.length}`);
940→
941→  const treesByItemKey = await requeryTrees(narrative, dbPath);
942→
943→  const html = renderHTML({ narrative, verdict, treesByItemKey });
944→
945→  const outPath = path.join(dir, 'report.html');
946→  fs.writeFileSync(outPath, html, 'utf-8');
947→
948→  const fileSizeKB = (fs.statSync(outPath).size / 1024).toFixed(1);
949→  console.log(`\n[render-html] Written: ${outPath}`);
950→  console.log(`[render-html] Size: ${fileSizeKB} KB`);
951→  console.log(`[render-html] Call-trees re-queried: ${treesByItemKey.size}`);
952→}
953→
954→main().catch(e => {
955→  console.error('[render-html] Fatal:', e);
956→  process.exit(1);
957→});
