  1→/**
  2→ * tools.ts — Prism B2 query tool layer
  3→ *
  4→ * 8 pure functions, each takes (db, args) and returns { data, provenance }.
  5→ * All aggregation happens in SQL or compact JS over query results.
  6→ * Token red-line: every tool returns ≤ ~50 rows / ≤ 2 KB.
  7→ *
  8→ * Exported pure helpers (for testing):
  9→ *   computeAutocorr(series: number[])  → { bestLag, coefficient } | null
 10→ *   computeStatsPack(values: number[], frameIndices?: number[])
 11→ */
 12→
 13→import type Database from 'better-sqlite3';
