 31→/**
 32→ * Compute normalized autocorrelation for lags 1..min(120, floor(n/2)).
 33→ * r(k) = Σ (x[i] - μ)(x[i+k] - μ)  /  Σ (x[i] - μ)²
 34→ * Returns { bestLag, coefficient } for the lag ≥ 2 with the highest r(k).
 35→ * Returns null if variance is zero or series is too short.
 36→ */
 37→export function computeAutocorr(
 38→  series: number[]
 39→): { bestLag: number; coefficient: number } | null {
 40→  const n = series.length;
 41→  if (n < 4) return null;
 42→
 43→  const mean = series.reduce((a, b) => a + b, 0) / n;
 44→  const centered = series.map(v => v - mean);
 45→  const denom = centered.reduce((a, b) => a + b * b, 0);
 46→  if (denom === 0) return null;
 47→
 48→  const maxLag = Math.min(120, Math.floor(n / 2));
 49→  let bestLag = 2;
 50→  let bestCoeff = -Infinity;
 51→
 52→  for (let k = 1; k <= maxLag; k++) {
 53→    let num = 0;
 54→    for (let i = 0; i < n - k; i++) {
 55→      num += centered[i] * centered[i + k];
 56→    }
 57→    const r = num / denom;
 58→    if (k >= 2 && r > bestCoeff) {
 59→      bestCoeff = r;
 60→      bestLag = k;
 61→    }
 62→  }
 63→
 64→  return { bestLag, coefficient: bestCoeff };
 65→}
