 67→/**
 68→ * Compute a statistics pack from a numeric array.
 69→ * frameIndices: parallel array of frame indices (same length as values).
 70→ * values may contain zeros (frames where metric was absent).
 71→ */
 72→export interface StatsPack {
 73→  frameCount: number;
 74→  presentFrames: number;
 75→  mean: number;
 76→  std: number;
 77→  p50: number;
 78→  p95: number;
 79→  p99: number;
 80→  max: number;
 81→  maxFrameIndex: number;
 82→  spikeRatio: number;
 83→  burstFrames: number[];
 84→  burstFramesTotal: number;
 85→  autocorr: { bestLag: number; coefficient: number } | null;
 86→}
 87→
 88→export function computeStatsPack(
 89→  values: number[],
 90→  frameIndices?: number[]
 91→): StatsPack {
 92→  const n = values.length;
 93→  const indices = frameIndices ?? values.map((_, i) => i + 1);
 94→
 95→  const sum = values.reduce((a, b) => a + b, 0);
 96→  const mean = n > 0 ? sum / n : 0;
 97→
 98→  const variance =
 99→    n > 0 ? values.reduce((a, v) => a + (v - mean) ** 2, 0) / n : 0;
100→  const std = Math.sqrt(variance);
