45→/** Load persistent brain entries and format as compact reference text for the explore prompt. */
46→export function formatMemoryForPrompt(opts?: FormatMemoryForPromptOptions): string {
47→  const { byCategory } = loadMemory({
48→    categories: MEMORY_INJECTION_CATEGORIES,
49→    root: opts?.root,
50→  });
51→
52→  // Per-category budget so a large category (e.g. 79 priors) can't starve
53→  // later categories (e.g. freshly-sedimented capabilities). Split the total
54→  // budget across categories that actually have entries.
55→  const activeCats = MEMORY_INJECTION_CATEGORIES.filter((c) => byCategory[c]?.length);
56→  if (activeCats.length === 0) return '';
57→  const perCatBudget = Math.floor(MEMORY_INJECTION_MAX_CHARS / activeCats.length);
58→
59→  const blocks: string[] = [];
60→
61→  for (const cat of activeCats) {
62→    const catEntries = byCategory[cat]!;
63→    const catLines: string[] = [`## ${cat} (${catEntries.length})`];
64→    let catChars = catLines[0].length + 1;
65→    let catTruncated = false;
66→    let shown = 0;
67→
68→    for (const entry of catEntries) {
69→      const title = entry.title ? String(entry.title) : entry.id;
70→      const compact = entry.content.replace(/\s+/g, ' ').trim();
71→      const summary = compact.length > 280 ? `${compact.slice(0, 277)}...` : compact;
72→      const line = `- [${title}] ${summary}`;
73→
74→      if (catChars + line.length + 1 > perCatBudget) {
75→        catTruncated = true;
76→        break;
77→      }
78→      catLines.push(line);
79→      catChars += line.length + 1;
80→      shown++;
