485→// ── 人话化：把 log 风的 finding claim 改成人话 ──
486→
487→function humanizeFinding(f: Finding): string {
488→  const name = extractDynamicName(f);
489→  const rb = f.relativeBaseline;
490→  const cc = f.causalChain;
491→
492→  // GPU-bound 因果推理 — 对齐 v5.3 §0①"主线程睡的时候 ~100% 在等 GPU"
493→  if (kindMatches(f.kind, 'gpu-bound-causal') && cc) {
494→    const coverageMatch = cc.inference.match(/effectiveCoveragePct[≈=]([\d.]+)/);
495→    const coverage = coverageMatch ? parseFloat(coverageMatch[1]) : null;
496→    if (coverage != null && Number.isFinite(coverage)) {
497→      return `throttle 上主线程 Sleeping 中约 ${coverage.toFixed(1)}% 是等 GPU（Gfx.WaitForPresent），GPU-bound 信号强烈。`;
498→    }
499→    return cc.conclusion;
500→  }
501→
502→  // off-CPU byState — 对齐 v5.3 §4 "Sleeping 占 off-CPU ~90%"
503→  if (kindMatches(f.kind, 'offcpu-bystate')) {
504→    const sMatch = f.claim.match(/S=([\d.]+)ms\(([\d.]+)%\)/);
505→    if (sMatch) {
506→      const sPct = parseFloat(sMatch[2]);
507→      return `throttle 主线程 off-CPU 中 S（Sleeping）占 ${sPct.toFixed(1)}%，即"等"绝大多数是主动睡（等事件），不是被抢占或等磁盘。`;
508→    }
509→    return f.claim;
510→  }
511→
512→  // 降频形态 — 对齐 v5.3 §5.2 形态识别
513→  if (kindMatches(f.kind, 'freq-morphology')) {
514→    const morph = extractMorphologyLabel(f.claim);
515→    const reachMatch = f.claim.match(/throttle=([\d.]+)/);
516→    const reach = reachMatch ? parseFloat(reachMatch[1]) : null;
517→    if (reach != null && Number.isFinite(reach)) {
518→      return `三态降频形态=${morph}：throttle 大核 reach 跌到 ${reach.toFixed(1)}%（cur 75.6% → throttle ${reach.toFixed(1)}%），全集群 reach 同向下降，是降频生效硬证。`;
519→    }
520→    return `三态降频形态=${morph}。`;
521→  }
522→
523→  // PlayerLoop 分位数 — 对齐 v5.3 §6.1
524→  if (kindMatches(f.kind, 'playerloop-percentiles', 'playerloop-percentile')) {
525→    const p50Match = f.claim.match(/p50=([\d.]+)/);
526→    const fpsMatch = f.claim.match(/fps=([\d.]+)/);
527→    const slowMatch = f.claim.match(/slowFrameRate=([\d.]+)/);
528→    const p50 = p50Match ? parseFloat(p50Match[1]) : null;
529→    const fps = fpsMatch ? parseFloat(fpsMatch[1]) : null;
530→    const slow = slowMatch ? parseFloat(slowMatch[1]) : null;
531→    if (p50 != null && fps != null && slow != null) {
532→      return `PlayerLoop p50=${p50.toFixed(2)}ms / fps=${fps.toFixed(1)} / 慢帧率=${slow.toFixed(2)}%（cur → throttle 持续匀慢型，非偶发尖峰）。`;
533→    }
534→    return f.claim;
535→  }
536→
537→  // 涨幅最大模块 — 对齐 v5.3 §0②"涨幅集中"
538→  if (kindMatches(f.kind, 'fold-change-module', 'rise-module') && rb) {
539→    const fc = rb.foldChange;
540→    if (fc != null && fc >= 9999) {
541→      return `${name}：仅在 ${rb.compareRole} 出现（base 无此节点），是 ${rb.compareRole} 阶段新增的消耗路径。`;
542→    }
543→    if (fc != null && Number.isFinite(fc)) {
544→      return `${name}：${rb.baselineRole} → ${rb.compareRole} 涨 ×${fc.toFixed(2)}，是相对涨幅最大的模块之一。`;
545→    }
546→    return `${name}：${rb.relativeJudgment}。`;
547→  }
548→
549→  // GC 压力 — 对齐 v5.3 §6.3 "GC.Alloc 业务归因"
550→  if (kindMatches(f.kind, 'gc-pressure-module', 'gc-pressure')) {
551→    const pf = extractPerFrame(f);
552→    if (pf != null) {
553→      return `${name}：GC.Alloc ${pf.toFixed(2)} 次/帧，是 GC 压力主要来源之一（perfetto 独家业务子树归因）。`;
554→    }
555→    return `${name}：GC 压力来源。`;
556→  }
557→
558→  // thermal-only 隐性路径 — 对齐 v5.3 §5.5
559→  if (kindMatches(f.kind, 'thermal-only-path', 'thermal-only') && rb) {
560→    const fc = rb.foldChange;
561→    if (fc != null && fc >= 9999) {
562→      return `${name}：仅在 throttle 出现（cur 无此节点），是降频阶段才暴露的隐性路径。`;
563→    }
564→    if (fc != null && Number.isFinite(fc)) {
565→      return `${name}：cur → throttle 涨 ×${fc.toFixed(2)}，是降频阶段才显著放大的路径。`;
566→    }
567→    return `${name}：thermal-only 隐性路径。`;
568→  }
569→
570→  // top 业务模块 — 对齐 v5.3 §6.2
571→  if (kindMatches(f.kind, 'top-business-module', 'top-business') && rb) {
572→    const fc = rb.foldChange;
573→    if (fc != null && Number.isFinite(fc)) {
574→      return `${name}：${rb.baselineRole} → ${rb.compareRole} 涨 ×${fc.toFixed(2)}（callTree 子树排名靠前）。`;
575→    }
576→    return `${name}：callTree 子树排名靠前。`;
577→  }
578→
579→  // 调度相对基线 — 对齐 v5.3 §0①
580→  if (kindMatches(f.kind, 'sched-relative') && rb) {
581→    return `${rb.baselineRole} → ${rb.compareRole}：${rb.relativeJudgment}。`;
582→  }
583→
584→  // 边界类
585→  if (kindMatches(f.kind, 'boundary')) {
586→    return f.claim;
587→  }
588→
589→  return f.claim;
590→}
