611→function buildRoiOptimizations(findings: Finding[]): RoiOptimization[] {
612→  type Draft = RoiOptimization & { sortFold: number; sortPerFrame: number };
613→  const drafts: Draft[] = [];
614→
615→  const rise = findings
616→    .filter((f) => kindMatches(f.kind, 'fold-change-module', 'rise-module'))
617→    .slice()
618→    .sort((a, b) => (b.relativeBaseline?.foldChange ?? 0) - (a.relativeBaseline?.foldChange ?? 0))
619→    .slice(0, 3);
620→  for (const f of rise) {
621→    const name = extractDynamicName(f);
622→    const fc = f.relativeBaseline?.foldChange;
623→    const fcLabel = fc != null && Number.isFinite(fc)
624→      ? (fc >= 9999 ? '新增' : `×${fc}`)
625→      : '（相对倍数见 finding）';
626→    const humanJudgment = humanizeRelativeJudgment(f.relativeBaseline);
627→    drafts.push({
628→      rank: 0,
629→      direction: `涨幅最大模块 ${name}：${f.relativeBaseline?.baselineRole} → ${f.relativeBaseline?.compareRole} ${fcLabel}，建议单次任务削峰 / 增量化 / 分帧`,
630→      rationale: humanJudgment ? `${f.relativeBaseline?.baselineRole} → ${f.relativeBaseline?.compareRole}：${humanJudgment}` : `依据 ${f.id}`,
631→      severity: f.severity,
632→      findingIds: [f.id],
633→      sortFold: fc ?? 0,
634→      sortPerFrame: 0,
635→    });
636→  }
637→
638→  const gc = findings
639→    .filter((f) => kindMatches(f.kind, 'gc-pressure-module', 'gc-pressure'))
640→    .slice()
641→    .sort((a, b) => (extractPerFrame(b) ?? 0) - (extractPerFrame(a) ?? 0))
642→    .slice(0, 2);
643→  for (const f of gc) {
644→    const name = extractDynamicName(f);
645→    const pf = extractPerFrame(f);
646→    const pfLabel = pf != null ? pf.toFixed(2) : '（见 claim）';
647→    const humanJudgment = humanizeRelativeJudgment(f.relativeBaseline);
648→    drafts.push({
649→      rank: 0,
650→      direction: `GC 压力最大模块 ${name}：${pfLabel} 次/帧，建议对象池 / 减少分配 / 字符串池化`,
651→      rationale: humanJudgment || `依据 ${f.id}`,
652→      severity: f.severity,
653→      findingIds: [f.id],
654→      sortFold: f.relativeBaseline?.foldChange ?? 0,
655→      sortPerFrame: pf ?? 0,
656→    });
657→  }
658→
659→  const gpu = findings.find(
660→    (f) =>
661→      kindMatches(f.kind, 'gpu-bound-causal') &&
662→      f.causalChain?.confidence === 'high',
663→  );
664→  if (gpu) {
665→    const humanInference = gpu.causalChain ? humanizeCausalInference(gpu.causalChain.inference) : gpu.claim;
666→    drafts.push({
667→      rank: 0,
668→      direction:
669→        'GPU-bound 信号强烈：主线程睡的时候接近 100% 在等 GPU，建议降分辨率 / 简化阴影 / MeshUI 顶点数评估 / drawcall 削减',
670→      rationale: humanInference,
671→      severity: gpu.severity,
672→      findingIds: [gpu.id],
673→      sortFold: 0,
674→      sortPerFrame: 0,
675→    });
676→  }
677→
678→  const freq = findings.find((f) => kindMatches(f.kind, 'freq-morphology'));
679→  if (freq) {
680→

680→    const morph = extractMorphologyLabel(freq.claim);
681→    const humanJudgment = humanizeRelativeJudgment(freq.relativeBaseline);
682→    drafts.push({
683→      rank: 0,
684→      direction: `降频形态=${morph}：建议温控策略评估 / 业务降级 / 场景级温度感知`,
685→      rationale: humanJudgment || `依据 ${freq.id}`,
686→      severity: freq.severity,
687→      findingIds: [freq.id],
688→      sortFold: freq.relativeBaseline?.foldChange ?? 0,
689→      sortPerFrame: 0,
690→    });
691→  }
692→
693→  const thermal = findings
694→    .filter((f) => kindMatches(f.kind, 'thermal-only-path', 'thermal-only'))
695→    .slice()
696→    .sort((a, b) => sevOrder(a.severity) - sevOrder(b.severity) ||
697→      (b.relativeBaseline?.foldChange ?? 0) - (a.relativeBaseline?.foldChange ?? 0))
698→    .slice(0, 1);
699→  for (const f of thermal) {
700→    const name = extractDynamicName(f);
701→    const humanJudgment = humanizeRelativeJudgment(f.relativeBaseline);
702→    drafts.push({
703→      rank: 0,
704→      direction: `thermal-only 隐性路径 ${name}：仅 throttle 出现，建议 thermal 路径专项排查`,
705→      rationale: humanJudgment || `依据 ${f.id}`,
706→      severity: f.severity,
707→      findingIds: [f.id],
708→      sortFold: f.relativeBaseline?.foldChange ?? 0,
709→      sortPerFrame: 0,
710→    });
711→  }
712→
713→  drafts.sort((a, b) => {
714→    const ds = sevOrder(a.severity) - sevOrder(b.severity);
715→    if (ds !== 0) return ds;
716→    if (b.sortFold !== a.sortFold) return b.sortFold - a.sortFold;
717→    return b.sortPerFrame - a.sortPerFrame;
718→  });
719→
720→  return drafts.map((d, i) => ({
721→    rank: i + 1,
722→    direction: d.direction,
723→    rationale: d.rationale,
724→    severity: d.severity,
725→    findingIds: d.findingIds,
726→  }));
727→}
