731→function buildMultiThreadMacro(
732→  triadSummaries: Record<Role, ProfileSummary>,
733→): PerfettoNarrative['multiThreadMacro'] {
734→  // 收集所有出现过的线程名（并集）
735→  const allThreadNames = new Set<string>();
736→  for (const role of ROLES) {
737→    const ts = triadSummaries[role].threadsSched ?? {};
738→    for (const name of Object.keys(ts)) allThreadNames.add(name);
739→  }
740→
741→  // 动态识别：按 atrace slice 内容 + comm 名推断通用名（不硬编码业务清单）
742→  // WT-024 需求 2：三态分别填充，不再"取最新可用"（throttle 覆盖 cur 覆盖 base）
743→  const threads: ThreadMacroRow[] = [];
744→  for (const name of allThreadNames) {
745→    const row: ThreadMacroRow = { name, commKey: name };
746→    for (const role of ROLES) {
747→      const entry = triadSummaries[role].threadsSched?.[name];
748→      if (entry) {
749→        row[role] = {
750→          runningPct: asNum(entry.runningPct) ?? null,
751→          sleepingPct: asNum(entry.sleepingPct) ?? null,
752→          runnablePct: asNum(entry.runnablePct) ?? null,
753→        };
754→      }
755→    }
756→    // 动态一句话定位（基于三态演化趋势，不硬编码业务名）
757→    const b = row.base, c = row.cur, t = row.throttle;
758→    if (b?.runningPct != null && c?.runningPct != null && t?.runningPct != null) {
759→      // 三态都有：描述演化趋势
760→      const runTrend = `${b.runningPct.toFixed(1)}→${c.runningPct.toFixed(1)}→${t.runningPct.toFixed(1)}`;
761→      const sleepTrend = b.sleepingPct != null && c.sleepingPct != null && t.sleepingPct != null
762→        ? `${b.sleepingPct.toFixed(1)}→${c.sleepingPct.toFixed(1)}→${t.sleepingPct.toFixed(1)}`
763→        : null;
764→      const runDecreasing = t.runningPct < b.runningPct;
765→      const sleepIncreasing = sleepTrend != null && (t.sleepingPct ?? 0) > (b.sleepingPct ?? 0);
766→      if (runDecreasing && sleepIncreasing) {
767→        row.note = `Run ${runTrend} 单调下降 / Sleep ${sleepTrend} 单调上升 → 越来越闲`;
768→      } else if (runDecreasing) {
769→        row.note = `Run ${runTrend} 单调下降`;
770→      } else if ((t.sleepingPct ?? 0) >= 90) {
771→        row.note = `Sleep ${t.sleepingPct?.toFixed(1)}% — 长期等待态，非瓶颈`;
772→      } else if ((t.runningPct ?? 0) >= 70) {
773→        row.note = `Run ${runTrend} — 高负载主线程形态`;
774→      } else {
775→        row.note = `Run ${runTrend}${sleepTrend ? ' / Sleep ' + sleepTrend : ''}`;
776→      }
777→    } else if (t?.runningPct != null && t.sleepingPct != null) {
778→      // 退化：只有 throttle
779→      if (t.sleepingPct >= 90) {
780→        row.note = `Sleep ${t.sleepingPct.toFixed(1)}% — 长期等待态，非瓶颈`;
781→      } else if (t.runningPct >= 70) {
782→        row.note = `Run ${t.runningPct.toFixed(1)}% — 高负载主线程形态`;
783→      } else if (t.runningPct >= 40) {
784→        row.note = `Run ${t.runningPct.toFixed(1)}% — 中等活跃`;
785→      } else {
786→        row.note = `Run ${t.runningPct.toFixed(1)}% / Sleep ${t.sleepingPct.toFixed(1)}%`;
787→      }
788→    }
789→    threads.push(row);
790→  }
791→
792→  // 排序：主线程优先（throttle runningPct 降序，退化用 cur/base），然后 sleepingPct 升序
793→  threads.sort((a, b) => {
794→    const aRun = a.throttle?.runningPct ?? a.cur?.runningPct ?? a.base?.runningPct ?? 0;
795→    const bRun = b.throttle?.runningPct ?? b.cur?.runningPct ?? b.base?.runningPct ?? 0;
796→    return bRun - aRun;
797→  });
798→
799→  return {
800→    threads,
801→    note: '线程通用名按 threadsSched key 动态识别；三态对照（base/cur/throttle）；一句话定位基于演化趋势（单调下降/上升），不硬编码业务名清单。',
802→  };
803→}
