805→// ── callTree 下钻：把 callTrees 转成缩进树结构 ──
806→
807→function convertCallTreeNode(
808→  node: CallTreeNode | undefined,
809→  depth: number,
810→  frameCount: number | null,
811→): CallTreeDrilldownNode[] {
812→  if (!node) return [];
813→  const totalMs = asNum(node.totalMs);
814→  const perFrameMs = totalMs != null && frameCount && frameCount > 0 ? totalMs / frameCount : undefined;
815→  const result: CallTreeDrilldownNode = {
816→    name: node.name,
817→    depth,
818→    totalMs: totalMs ?? undefined,
819→    totalPct: asNum(node.totalPct) ?? undefined,
820→    count: asNum(node.count) ?? undefined,
821→    layer: node.layer,
822→    perFrameMs: perFrameMs,
823→    children: [],
824→  };
825→  if (node.children && node.children.length > 0) {
826→    result.children = node.children.flatMap((c) => convertCallTreeNode(c, depth + 1, frameCount));
827→  }
828→  return [result];
829→}
830→
831→function buildCallTreeDrilldown(
832→  role: Role,
833→  summary: ProfileSummary,
834→): PerfettoNarrative['callTreeDrilldown'][Role] {
835→  const trees = summary.callTrees ?? [];
836→  const playerLoopFrame = summary.frame?.find((f) => f.frameDefinition === 'playerloop');
837→  const frameCount = asNum(playerLoopFrame?.count) ?? null;
838→  if (trees.length === 0) {
839→    return { available: false, tree: [], playerLoopFrameCount: frameCount, note: 'callTree 不可用' };
840→  }
841→  // 取 UnityMain 主树
842→  const mainTree = trees.find((t) => t.thread === 'UnityMain') ?? trees[0];
843→  const flatTree = convertCallTreeNode(mainTree.root, 0, frameCount);
844→  return {
845→    available: true,
846→    tree: flatTree,
847→    playerLoopFrameCount: frameCount,
848→    note: `主树=${mainTree.thread}；perFrameMs = totalMs / PlayerLoop 帧数(${frameCount ?? '?'})`,
849→  };
850→}
