852→// ── off-CPU 归因：byState 三态对照 + wait slice 重叠 + ASCII ──
853→
854→function buildOffCpuAttribution(
855→  triadSummaries: Record<Role, ProfileSummary>,
856→  ledger: LedgerFile,
857→  parentChains: Map<string, NameParentChain>,
858→): PerfettoNarrative['offCpuAttribution'] {
859→  // byState 三态对照
860→  const stateOrder = ['S', 'R', 'R+', 'D'];
861→  const byState: OffCpuStateRow[] = stateOrder.map((state) => {
862→    const row: OffCpuStateRow = { state };
863→    for (const role of ROLES) {
864→      const offCpu = triadSummaries[role].offCpuAttribution ?? triadSummaries[role].offCpuReasons;
865→      const entry = offCpu?.byState?.find((s) => s.state === state);
866→      if (entry) {
867→        (row as Record<Role, { totalMs: number; pctOfOffCpu: number }>)[role] = {
868→          totalMs: entry.totalMs,
869→          pctOfOffCpu: entry.pctOfOffCpu ?? 0,
870→        };
871→      }
872→    }
873→    return row;
874→  });
875→
876→  // wait slice 重叠：从 ledger ev-025-throttle-queryOffCpuAttribution 拿 waitSlices
877→  // 若 ledger 没有该 role 的 evidence（base/cur 未跑 queryOffCpuAttribution），
878→  // 则从 callTree 递归找 Gfx.WaitForPresentOnGfxThread / URP.WaitForPresent 节点
879→  const findWaitSliceInCallTree = (node: CallTreeNode | undefined): { name: string; totalMs: number } | null => {
880→    if (!node) return null;
881→    const name = node.name;
882→    if (/Gfx\.WaitForPresent/i.test(name) || /URP\.WaitForPresent/i.test(name)) {
883→      const totalMs = asNum(node.totalMs);
884→      if (totalMs != null && totalMs > 0) return { name, totalMs };
885→    }
886→    if (node.children) {
887→      // 优先找 Gfx.WaitForPresentOnGfxThread（最精确）
888→      for (const c of node.children) {
889→        const r = findWaitSliceInCallTree(c);
890→        if (r && /Gfx\.WaitForPresent/i.test(r.name)) return r;
891→      }
892→      // 退化找 URP.WaitForPresent
893→      for (const c of node.children) {
894→        const r = findWaitSliceInCallTree(c);
895→        if (r) return r;
896→      }
897→    }
898→    return null;
899→  };
900→
901→  const waitSliceOverlap = {} as PerfettoNarrative['offCpuAttribution']['waitSliceOverlap'];
902→  for (const role of ROLES) {
903→    const offCpuEv = evidenceByToolRole(ledger, 'queryOffCpuAttribution', role);
904→    const offCpuFacts = asRec(offCpuEv?.facts);
905→    const waitSlices = Array.isArray(offCpuFacts.waitSlices) ? offCpuFacts.waitSlices : [];
906→    // 优先从 ledger waitSlices 找
907→    let gfxWait: { name: string; totalMs: number } | null = null;
908→    const ledgerGfxWait = waitSlices.find((w) => {
909→      const name = String(asRec(w).name ?? '');
910→      return /Gfx\.WaitForPresent/i.test(name);
911→    }) ?? waitSlices.find((w) => /WaitForPresent/i.test(String(asRec(w).name ?? '')));
912→    if (ledgerGfxWait) {
913→      const name = String(asRec(ledgerGfxWait).name ?? '');
914→      const totalMs = asNum(asRec(ledgerGfxWait).totalMs);
915→      if (totalMs != null) gfxWait = { name, totalMs };
916→    }
917→    // 若 ledger 没有，从 callTree 找
918→    if (!gfxWait) {
919→      const mainTree = triadSummaries[role].callTrees?.find((t) => t.thread === 'UnityMain');
920→      gfxWait = findWaitSliceInCallTree(mainTree?.root);
921→    }
922→    const sleepingMs = asNum(offCpuFacts.sleepingMs) ?? null;
923→    // sleepingMs in ledger facts 是 sched sleepingPct × totalOffCpuMs 的近似；
924→    // 更准确用 byState.S.totalMs
925→    const sState = triadSummaries[role].offCpuAttribution?.byState?.find((s) => s.state === 'S');
926→    const sTotalMs = asNum(sState?.totalMs) ?? sleepingMs;
927→    const maxWaitSlice = gfxWait?.name ?? null;
928→    const maxWaitMs = gfxWait?.totalMs ?? null;
929→    const coveragePct = sTotalMs != null && maxWaitMs != null && sTotalMs > 0
930→      ? (maxWaitMs / sTotalMs) * 100
931→      : null;
932→    (waitSliceOverlap as Record<Role, typeof waitSliceOverlap[Role]>)[role] = {
933→      sleepingMs: sTotalMs,
934→      maxWaitSlice,
935→      maxWaitMs,
936→      coveragePct,
937→    };
938→  }
939→
940→  // ASCII 状态分布 — 对齐 v5.3 §4.4
941→  const asciiStateDistribution = buildAsciiStateDistribution(triadSummaries);
942→
943→  // ASCII 因果链 — 对齐 v5.3 §4.5
944→  const asciiCausalChain = buildAsciiCausalChain(triadSummaries, waitSliceOverlap, parentChains);
945→
946→  return {
947→    byState,
948→    waitSliceOverlap,
949→    asciiStateDistribution,
950→    asciiCausalChain,
951→    note: 'byState 三态对照 + wait slice 重叠法（atrace wait slice vs sched Sleeping）；byReason 因 sched_blocked_reason ftrace 缺失不可用，用 wait slice 重叠旁路。',
952→  };
953→}
