955→function buildAsciiStateDistribution(
956→  triadSummaries: Record<Role, ProfileSummary>,
957→): string {
958→  const lines: string[] = [];
959→  lines.push('主线程状态分布对比（归一化为整 trace 窗口）');
960→

 960→  lines.push('');
 961→  for (const role of ROLES) {
 962→    const sched = triadSummaries[role].threadsSched?.['UnityMain'];
 963→    const run = sched?.runningPct;
 964→    const sleep = sched?.sleepingPct;
 965→    const runn = sched?.runnablePct;
 966→    if (run == null || sleep == null) continue;
 967→    const runBar = '█'.repeat(Math.round(run / 3));
 968→    const sleepBar = '░'.repeat(Math.round(sleep / 3));
 969→    lines.push(`${role.padEnd(10)} ${runBar}${sleepBar}  Run ${run.toFixed(2)}% / Sleep ${sleep.toFixed(2)}% / Runn ${(runn ?? 0).toFixed(2)}%`);
 970→    // 动态注解（基于相对形态变化，不硬编码绝对阈值）
 971→    if (role === 'base') {
 972→      lines.push(`           ↑ base 形态：${sleep < 15 ? '低 Sleep，CPU-bound 健康态' : 'Sleep 偏高'}`);
 973→    } else if (role === 'cur') {
 974→      const sleepDelta = sleep - (triadSummaries.base.threadsSched?.['UnityMain']?.sleepingPct ?? 0);
 975→      lines.push(`           ↑ cur 比 base Sleep 多 ${sleepDelta.toFixed(2)}pp`);
 976→    } else if (role === 'throttle') {
 977→      const sleepDelta = sleep - (triadSummaries.cur.threadsSched?.['UnityMain']?.sleepingPct ?? 0);
 978→      lines.push(`           ↑ throttle 比 cur Sleep 多 ${sleepDelta.toFixed(2)}pp（半睡型）`);
 979→    }
 980→  }
 981→  return lines.join('\n');
 982→}
