 984→function buildAsciiCausalChain(
 985→  triadSummaries: Record<Role, ProfileSummary>,
 986→  waitSliceOverlap: PerfettoNarrative['offCpuAttribution']['waitSliceOverlap'],
 987→  parentChains: Map<string, NameParentChain>,
 988→): string {
 989→  const lines: string[] = [];
