 991→  lines.push('');
 992→  lines.push('  主线程发起 PostLateUpdate.FinishFrameRendering');
 993→  // WT-024 需求 6：从 parentChains 动态提取 wait slice 的祖先链，不硬编码业务名
 994→  const throttleWait = waitSliceOverlap.throttle;
 995→  const waitSliceName = throttleWait?.maxWaitSlice ?? null;
 996→  const waitChain = waitSliceName ? parentChains.get(waitSliceName) : undefined;
 997→  if (waitChain && waitChain.parentChain.length > 0) {
 998→    // parentChain 是从 root 到该节点的祖先链（不含自身），倒序展示从主入口到 wait slice
 999→    // 过滤掉 PlayerLoop 等顶层 wrapper，从第一个业务层祖先开始
1000→    const filteredAncestors = waitChain.parentChain.filter(
