1009→    lines.push(`    → ${waitSliceName}`);
1010→  } else {
1011→    lines.push('    → （wait slice 数据不可用）');
1012→  }
1013→  lines.push('    │');
1014→  lines.push('    ├─ 状态切换为 Sleep (S, sched off-CPU 主态)');
1015→  lines.push('    │');
1016→  if (throttleWait?.maxWaitSlice && throttleWait.maxWaitMs != null) {
1017→    lines.push(`    └─ 等 swapchain Present 信号 (${throttleWait.maxWaitSlice} 累计 ${throttleWait.maxWaitMs.toFixed(0)}ms)`);
1018→  } else {
1019→    lines.push('    └─ 等 swapchain Present 信号');
1020→  }
1021→  lines.push('            │');
1022→  lines.push('            └─ 信号源 = GPU 完成上一帧 swapchain present');
1023→  lines.push('                    │');
1024→  lines.push('                    └─ 真因双重叠加：');
1025→  lines.push('                        (1) GPU 处理一帧本身要 ~Nms（无 GPU busy counter，量化不到）');
1026→  lines.push('                        (2) swapchain 排队 — 前一帧没 present 完，下一帧得排队等');
1027→  lines.push('');
1028→  lines.push('证据链一致性检查（多信号同向）：');
1029→  const mainSched = triadSummaries.throttle.threadsSched?.['UnityMain'];
1030→  const renderSched = triadSummaries.throttle.threadsSched?.['UnityGfxRenderS'];
1031→  const baseMain = triadSummaries.base.threadsSched?.['UnityMain'];
1032→  const curMain = triadSummaries.cur.threadsSched?.['UnityMain'];
1033→  const baseRender = triadSummaries.base.threadsSched?.['UnityGfxRenderS'];
1034→  const curRender = triadSummaries.cur.threadsSched?.['UnityGfxRenderS'];
1035→  if (mainSched && throttleWait?.coveragePct != null) {
1036→    lines.push(`- 主线程 Sleep ${mainSched.sleepingPct?.toFixed(2)}% ≈ ${throttleWait.maxWaitSlice} ${throttleWait.maxWaitMs?.toFixed(0)}ms (重合 ${throttleWait.coveragePct.toFixed(1)}%) ✅`);
1037→  }
1038→  if (baseMain && curMain && mainSched) {
1039→    lines.push(`- 主线程 Run ${baseMain.runningPct?.toFixed(2)}% → ${curMain.runningPct?.toFixed(2)}% → ${mainSched.runningPct?.toFixed(2)}% (单调下降) ✅`);
1040→  }
1041→  if (baseRender && curRender && renderSched) {
1042→    lines.push(`- Render Run ${baseRender.runningPct?.toFixed(2)}% → ${curRender.runningPct?.toFixed(2)}% → ${renderSched.runningPct?.toFixed(2)}% (同步变闲) ✅`);
1043→  }
1044→  const throttleReach = triadSummaries.throttle.throttling?.bigCoreReachPct;
1045→  if (throttleReach != null) {
1046→    lines.push(`- bigCoreReach ${throttleReach.toFixed(1)}% (严重低频) → CPU 算得也慢，加重 swapchain 排队 ✅`);
1047→  }
1048→  lines.push('');
1049→  lines.push('排除项（数据排除的瓶颈方向）：');
1050→  lines.push('- ❌ binder IPC 阻塞 → 主线程 binder 累计 < 0.05% trace');
1051→  lines.push('- ❌ ECS Worker 阻塞 → 4 条 Worker 偏差 < 1pp（健康）');
1052→  lines.push('- ❌ Lua GC spike → LuaMtGC Sleep ≥97%');
1053→  return lines.join('\n');
