1159→function buildAsciiFreqMorphology(
1160→  triadSummaries: Record<Role, ProfileSummary>,
1161→): string {
1162→  const lines: string[] = [];
1163→  lines.push('三态降频形态对比：');
1164→  lines.push('');
1165→  for (const role of ROLES) {
1166→    const t = triadSummaries[role].throttling;
