1168→    const avgMhz = triadSummaries[role].system?.cpuFreqAvgMhz;
1169→    const thermal = t?.thermal;
1170→    const run = triadSummaries[role].threadsSched?.['UnityMain']?.runningPct;
1171→    if (reach == null) continue;
1172→    lines.push(`${role.padEnd(10)}:`);
1173→    lines.push(`  特征: 温度 ${thermal?.beforeC?.toFixed(1) ?? '?'} → ${thermal?.afterC?.toFixed(1) ?? '?'}°C (Δ ${thermal?.deltaC != null ? (thermal.deltaC > 0 ? '+' : '') + thermal.deltaC.toFixed(1) : '?'}°C)`);
1174→    lines.push(`        bigReach ${reach.toFixed(1)}% / avgMhz ${avgMhz?.toFixed(1) ?? '?'} / UnityMain Run ${run?.toFixed(2) ?? '?'}%`);
1175→    // 动态形态识别（基于相对变化，不硬编码绝对阈值）
1176→    const prevRole = role === 'cur' ? 'base' : role === 'throttle' ? 'cur' : null;
1177→    const prevReach = prevRole ? triadSummaries[prevRole as Role].throttling?.bigCoreReachPct : null;
1178→    if (prevReach != null) {
1179→      const delta = reach - prevReach;
1180→      if (delta < -10) {
1181→        lines.push(`  形态: "重度降频，reach 暴跌 ${Math.abs(delta).toFixed(1)}pp"`);
1182→      } else if (delta < -3) {
1183→        lines.push(`  形态: "reach 小幅下降 ${delta.toFixed(1)}pp"`);
1184→      } else {
1185→        lines.push(`  形态: "reach 持平 (${delta >= 0 ? '+' : ''}${delta.toFixed(1)}pp)"`);
1186→      }
1187→    } else {
1188→      const dC = thermal?.deltaC;
1189→      if (dC != null && dC >= 5) {
1190→        lines.push(`  形态: "凉机起步进热保护（Δ +${dC.toFixed(1)}°C）"`);
1191→      } else if (thermal?.beforeC != null && thermal.beforeC >= 75) {
1192→        lines.push(`  形态: "起点已饱和（${thermal.beforeC.toFixed(1)}°C ≥ 75°C）"`);
1193→      } else {
1194→        lines.push(`  形态: "温度走平"`);
1195→      }
1196→    }
1197→    lines.push('');
1198→  }
1199→  return lines.join('\n').trimEnd();
1200→}
