1202→// ── 子树归并：从 callTree 动态构建 name → parentChain 映射（DR-41 规则 2） ──
1203→
1204→/**
1205→ * 遍历 callTree，为每个节点构建 parentChain（祖先链，不含自身）。
1206→ * 用于子树归并：若 A 的 parentChain 包含 B，则 A 是 B 的后代，归并到 B。
1207→ *
1208→ * WT-025 需求 2：核心逻辑已抽到 report-utils.ts 的 buildNameParentChains（数据源无关）。
1209→ * 本函数是 Perfetto 适配器：从 triadSummaries 选主参考 callTree + frameCount，
1210→ * 调用通用版本。
1211→ */
1212→function buildNameParentChains(
1213→  triadSummaries: Record<Role, ProfileSummary>,
1214→): Map<string, NameParentChain> {
1215→  // 用 cur 的 callTree 作为主参考（最完整 + 业务热点最显著）
1216→  // 若 cur 缺失则用 throttle
1217→  const refRole: Role = triadSummaries.cur.callTrees && triadSummaries.cur.callTrees.length > 0
1218→    ? 'cur'
1219→    : 'throttle';
1220→  const summary = triadSummaries[refRole];
1221→  const trees = summary.callTrees ?? [];
1222→  const mainTree = trees.find((t) => t.thread === 'UnityMain') ?? trees[0];
1223→  if (!mainTree) return new Map();
1224→  const frameCount = summary.frame?.find((f) => f.frameDefinition === 'playerloop')?.count ?? 0;
1225→  // CallTreeNode 结构兼容 ReportTreeNode（name/totalMs/totalPct/count/children）
1226→  return buildNameParentChainsGeneric(mainTree.root as unknown as ReportTreeNode, frameCount);
1227→}
