1229→// isAncestorOf / mergeBySubtree 已从 report-utils.ts 导入（WT-025 需求 2）
1230→
1231→// ── 红线矩阵：从 callTree + findings 动态提取 ──
1232→
1233→function buildRedlineMatrix(
1234→  triadSummaries: Record<Role, ProfileSummary>,
1235→  findings: Finding[],
1236→  parentChains: Map<string, NameParentChain>,
1237→): PerfettoNarrative['redlineMatrix'] {
1238→  // 从 callTree 提取三态共有的业务模块（layer=business 或 depth≥3 的节点）
1239→  // 按 cur perFrameMs 降序，取 top 12 后做子树归并（DR-41 规则 2），最终保留 top 8
1240→  type ModuleEntry = {
1241→    name: string;
1242→    basePerFrameMs: number | null;
1243→    curPerFrameMs: number | null;
1244→    throttlePerFrameMs: number | null;
1245→    baseTotalMs: number | null;
1246→    curTotalMs: number | null;
1247→    throttleTotalMs: number | null;
1248→    childHotspot?: string;
1249→    mergedChildren?: string[];
1250→  };
1251→
1252→  // 收集三态 callTree 中所有节点（按 name 聚合）
1253→  const collectNodes = (role: Role): Map<string, { totalMs: number; perFrameMs: number; count: number; childHotspot?: string }> => {
1254→    const result = new Map<string, { totalMs: number; perFrameMs: number; count: number; childHotspot?: string }>();
1255→    const summary = triadSummaries[role];
1256→    const frameCount = summary.frame?.find((f) => f.frameDefinition === 'playerloop')?.count ?? 0;
1257→    const trees = summary.callTrees ?? [];
1258→    const mainTree = trees.find((t) => t.thread === 'UnityMain') ?? trees[0];
1259→    if (!mainTree) return result;
1260→

1260→
1261→    const walk = (node: CallTreeNode | undefined, parentName?: string) => {
1262→      if (!node) return;
1263→      const totalMs = asNum(node.totalMs);
1264→      if (totalMs != null && totalMs > 0) {
1265→        const perFrameMs = frameCount > 0 ? totalMs / frameCount : 0;
1266→        const existing = result.get(node.name);
1267→        if (existing) {
1268→          // 取最大值（避免父子重复时取父）
1269→          if (totalMs > existing.totalMs) {
1270→            result.set(node.name, { totalMs, perFrameMs, count: asNum(node.count) ?? existing.count, childHotspot: existing.childHotspot });
1271→          }
1272→        } else {
1273→          result.set(node.name, { totalMs, perFrameMs, count: asNum(node.count) ?? 0 });
1274→        }
1275→        // 记录子节点热点（最大子节点）
1276→        if (node.children && node.children.length > 0) {
1277→          const topChild = node.children
1278→            .map((c) => ({ name: c.name, totalMs: asNum(c.totalMs) ?? 0 }))
1279→            .sort((a, b) => b.totalMs - a.totalMs)[0];
1280→          if (topChild && topChild.totalMs > 0) {
1281→            const cur = result.get(node.name);
1282→            if (cur && (!cur.childHotspot || topChild.totalMs > 0)) {
1283→              cur.childHotspot = topChild.name;
1284→            }
1285→          }
1286→        }
1287→      }
1288→      if (node.children) {
1289→        for (const c of node.children) walk(c, node.name);
1290→      }
1291→    };
1292→    walk(mainTree.root);
1293→    return result;
1294→  };
1295→
1296→  const baseMap = collectNodes('base');
1297→  const curMap = collectNodes('cur');
1298→  const throttleMap = collectNodes('throttle');
1299→
1300→  // 取三态中至少两态出现的节点（避免只出现一次的剪枝噪声）
1301→  const allNames = new Set<string>();
1302→  for (const name of curMap.keys()) allNames.add(name);
1303→  for (const name of throttleMap.keys()) allNames.add(name);
1304→
1305→  const entries: ModuleEntry[] = [];
1306→  for (const name of allNames) {
1307→    const cur = curMap.get(name);
1308→    const throttle = throttleMap.get(name);
1309→    const base = baseMap.get(name);
1310→    // 过滤：只保留 cur 或 throttle 有显著消耗的（perFrameMs > 0.3ms）
1311→    const curPerFrame = cur?.perFrameMs ?? null;
1312→    const throttlePerFrame = throttle?.perFrameMs ?? null;
1313→    if ((curPerFrame ?? 0) < 0.3 && (throttlePerFrame ?? 0) < 0.3) continue;
1314→    // 过滤掉纯引擎根（PlayerLoop/UnityMain/PostLateUpdate.FinishFrameRendering 等顶层）
1315→    if (/^(UnityMain|PlayerLoop|PostLateUpdate\.FinishFrameRendering|Update\.ScriptRunBehaviourUpdate|PreLateUpdate\.ScriptRunBehaviourLateUpdate|BehaviourUpdate|LateBehaviourUpdate)$/.test(name)) continue;
1316→    entries.push({
1317→      name,
1318→      basePerFrameMs: base?.perFrameMs ?? null,
1319→      curPerFrameMs: curPerFrame,
1320→      throttlePerFrameMs: throttlePerFrame,
1321→      baseTotalMs: base?.totalMs ?? null,
1322→      curTotalMs: cur?.totalMs ?? null,
1323→      throttleTotalMs: throttle?.totalMs ?? null,
1324→      childHotspot: cur?.childHotspot ?? throttle?.childHotspot,
1325→    });
1326→  }
1327→
1328→  // 按 cur perFrameMs 降序，取 top 12 候选（归并后可能压缩到 6-8 行）
1329→  entries.sort((a, b) => (b.curPerFrameMs ?? 0) - (a.curPerFrameMs ?? 0));
1330→  const candidates = entries.slice(0, 12);
1331→
1332→  // 子树归并（DR-41 规则 2）：若祖先已在列表里，child 不单独成行
1333→  const merged = mergeBySubtree(candidates, parentChains, (e) => e.name);
1334→  const topEntries = merged.slice(0, 8);
1335→
1336→  // 动态匹配 finding（按 name 包含 finding 的动态名）
1337→  const rows: RedlineMatrixRow[] = topEntries.map((e, i) => {
1338→    const matchingFinding = findings.find((f) => {
1339→      const fName = extractDynamicName(f);
1340→      return fName.includes(e.name) || e.name.includes(fName);
1341→    });
1342→    // 动态红线判定（基于相对倍数，不硬编码绝对阈值）
1343→    const foldCurBase = e.basePerFrameMs != null && e.basePerFrameMs > 0
1344→      ? (e.curPerFrameMs ?? 0) / e.basePerFrameMs
1345→      : null;
1346→    const foldThrottleCur = e.curPerFrameMs != null && e.curPerFrameMs > 0
1347→      ? (e.throttlePerFrameMs ?? 0) / e.curPerFrameMs
1348→      : null;
1349→    let redlineType = '🟢 健康';
1350→    if (foldCurBase != null && foldCurBase >= 2) redlineType = '🔴 cur 涨幅显著 (×' + foldCurBase.toFixed(2) + ')';
1351→    else if (foldThrottleCur != null && foldThrottleCur >= 1.5) redlineType = '🔴 throttle 涨幅显著 (×' + foldThrottleCur.toFixed(2) + ')';
1352→    else if ((e.curPerFrameMs ?? 0) >= 1.0 || (e.throttlePerFrameMs ?? 0) >= 1.0) redlineType = '🟡 临近红线';
1353→
1354→    return {
1355→      rank: i + 1,
1356→      module: e.name,
1357→      curPerFrameMs: e.curPerFrameMs,
1358→      throttlePerFrameMs: e.throttlePerFrameMs,
1359→      basePerFrameMs: e.basePerFrameMs,
1360→      foldChangeCurVsBase: foldCurBase,
1361→      foldChangeThrottleVsCur: foldThrottleCur,
1362→      redlineType,
1363→      childHotspot: e.childHotspot,
1364→      findingId: matchingFinding?.id,
1365→      mergedChildren: (e as ModuleEntry & { mergedChildren?: string[] }).mergedChildren,
1366→    };
1367→  });
1368→
1369→  return {
1370→    rows,
1371→    note: '红线矩阵按 cur perFrameMs 降序取 top 候选，再做子树归并（DR-41 规则 2：parentChain 包含关系，child 不单独成行）；红线判定用相对倍数（涨幅 ≥2× 显著 / perFrame ≥1.0ms 临近），不硬编码业务名清单或绝对阈值。',
1372→  };
1373→}
