1446→// ── §0 三大独立结论的图文穿插四段式块（DR-41 规则 4） ──
1447→
1448→// buildAsciiBar 已从 report-utils.ts 导入（WT-025 需求 2）
1449→
1450→function buildTopConclusionBlocks(
1451→  triadSummaries: Record<Role, ProfileSummary>,
1452→  waitSliceOverlap: PerfettoNarrative['offCpuAttribution']['waitSliceOverlap'],
1453→  findings: Finding[],
1454→  parentChains: Map<string, NameParentChain>,
1455→): TopConclusionBlock[] {
1456→  const blocks: TopConclusionBlock[] = [];
1457→
1458→  // ── ① GPU-bound：主线程睡的时候 ~100% 在等 GPU（对应 v5.3 §0①）──
1459→  const baseSched = triadSummaries.base.threadsSched?.['UnityMain'];
1460→  const curSched = triadSummaries.cur.threadsSched?.['UnityMain'];
1461→  const throttleSched = triadSummaries.throttle.threadsSched?.['UnityMain'];
1462→  const baseWait = waitSliceOverlap.base;
1463→  const curWait = waitSliceOverlap.cur;
1464→  const throttleWait = waitSliceOverlap.throttle;
1465→  const gpuFinding = findings.find((f) => kindMatches(f.kind, 'gpu-bound-causal'));
1466→
1467→  if (baseSched && curSched && throttleSched) {
1468→    const runBase = baseSched.runningPct ?? 0;
1469→    const runCur = curSched.runningPct ?? 0;
1470→    const runThrottle = throttleSched.runningPct ?? 0;
1471→    const sleepBase = baseSched.sleepingPct ?? 0;
1472→    const sleepCur = curSched.sleepingPct ?? 0;
1473→    const sleepThrottle = throttleSched.sleepingPct ?? 0;
1474→    const waitBasePct = baseWait?.coveragePct ?? 0;
1475→    const waitCurPct = curWait?.coveragePct ?? 0;
1476→    const waitThrottlePct = throttleWait?.coveragePct ?? 0;
1477→
1478→    const asciiLines: string[] = [
1479→      '主线程 Running / Sleeping（三态对比）:',
1480→      `  base       ${buildAsciiBar(runBase, 100)}  Run ${runBase.toFixed(1)}% / Sleep ${sleepBase.toFixed(1)}%`,
1481→      `  cur        ${buildAsciiBar(runCur, 100)}  Run ${runCur.toFixed(1)}% / Sleep ${sleepCur.toFixed(1)}%`,
1482→      `  throttle   ${buildAsciiBar(runThrottle, 100)}  Run ${runThrottle.toFixed(1)}% / Sleep ${sleepThrottle.toFixed(1)}%`,
1483→      '',
1484→      '主线程 Sleeping 中等 GPU 占比（wait slice 重叠法）:',
1485→      `  base       ${buildAsciiBar(waitBasePct, 100)}  ${waitBasePct.toFixed(1)}%`,
1486→      `  cur        ${buildAsciiBar(waitCurPct, 100)}  ${waitCurPct.toFixed(1)}%`,
1487→      `  throttle   ${buildAsciiBar(waitThrottlePct, 100)}  ${waitThrottlePct.toFixed(1)}%`,
1488→    ];
1489→
1490→    const keyNumbers: string[] = [];
1491→    if (throttleWait?.maxWaitMs != null) {
1492→      const avgPerFrame = triadSummaries.throttle.frame?.find((f) => f.frameDefinition === 'playerloop')?.count
1493→        ? (throttleWait.maxWaitMs / (triadSummaries.throttle.frame?.find((f) => f.frameDefinition === 'playerloop')?.count ?? 1))
1494→        : null;
1495→      if (avgPerFrame != null) {
1496→        keyNumbers.push(`throttle 单帧平均等 GPU ${avgPerFrame.toFixed(2)}ms（${avgPerFrame > 16.66 ? '已超 60Hz vsync 周期 16.66ms → swapchain 撑爆' : '未超 vsync 周期'}）。`);
1497→      }
1498→    }
1499→    const sleepDelta = sleepThrottle - sleepBase;
1500→    keyNumbers.push(`Sleep 增量 ${sleepDelta.toFixed(1)}pp 中约 ${waitThrottlePct.toFixed(0)}% 来自等 GPU。`);
1501→
1502→    blocks.push({
1503→      rank: 1,
1504→      tag: '①',
1505→      severity: 'critical',
1506→      oneLiner: '主线程瓶颈形态：从 base 的"几乎全程在算"演化到 throttle 的"半睡型"——核心增量是等 GPU，不是等锁/binder。',
1507→      asciiChart: asciiLines.join('\n'),
1508→      keyNumbers,
1509→      seeAlso: '详见 §3',
1510→      findingIds: gpuFinding ? [gpuFinding.id] : [],
1511→    });
1512→  }
1513→
1514→  // ── ② 业务侧主入口涨幅（对应 v5.3 §0②）──
1515→  // WT-024 需求 1：合并 fold-change-module（新增路径）+ top-business-module（现存大头），
1516→  // 子树归并后取 top 2-3 条独立子树，每条含三态 perFrameMs + 涨幅 + 子热点
1517→  const riseFindings = findings
1518→    .filter((f) => kindMatches(f.kind, 'fold-change-module', 'rise-module', 'top-business-module'))
1519→    .map((f) => ({
1520→      f,
1521→      name: extractDynamicName(f),
1522→      fold: f.relativeBaseline?.foldChange ?? 0,
1523→      curTotalMs: parseFloat((f.relativeBaseline?.absoluteValue ?? '').match(/totalMs=([\d.]+)/)?.[1] ?? '0') || 0,
1524→    }))
1525→    .sort((a, b) => b.fold - a.fold || b.curTotalMs - a.curTotalMs);
1526→
1527→  // 从 callTree 提取三态 perFrameMs 的辅助函数（供多个子树复用）
1528→  const findPerFrame = (name: string, role: Role): number | null => {
1529→    const summary = triadSummaries[role];
1530→    const frameCount = summary.frame?.find((f) => f.frameDefinition === 'playerloop')?.count ?? 0;
1531→    if (frameCount === 0) return null;
1532→    const trees = summary.callTrees ?? [];
1533→    const mainTree = trees.find((t) => t.thread === 'UnityMain') ?? trees[0];
1534→    if (!mainTree) return null;
1535→    let result: number | null = null;
1536→    const walk = (n: CallTreeNode | undefined) => {
1537→      if (!n) return;
1538→      if (n.name === name) {
1539→        const t = asNum(n.totalMs);
1540→

1540→        if (t != null) result = t / frameCount;
1541→      }
1542→      if (n.children) for (const c of n.children) walk(c);
1543→    };
1544→    walk(mainTree.root);
1545→    return result;
1546→  };
1547→
1548→  // 子树归并：取 top 6 候选，归并后取 top 3 作为主结论（不是 top 1）
1549→  const riseCandidates = riseFindings.slice(0, 6).map((r) => ({ module: r.name, finding: r.f }));
1550→  const riseMerged = mergeBySubtree(
1551→    riseCandidates.map((r) => ({ module: r.module, mergedChildren: [] as string[] })),
1552→    parentChains,
1553→    (r) => r.module,
1554→  );
1555→  // 取 top 3 独立子树
1556→  const topRiseSubtrees = riseMerged.slice(0, 3).map((entry) => {
1557→    const name = entry.module;
